def make_textbook_entry(content_dict, length="medium", ttype="unit_lesson", tags=None):
    return {
        "subject": content_dict["subject"], "topic": content_dict["topic"], "level": content_dict["level"],
        "length": length, "type": ttype, "title": content_dict["title"],
        "tags": tags or [], "content": content_dict,
        "status": "published", "source": "claude_max_seed_batch19",
    }

textbooks = [
    make_textbook_entry(KEIGO_TEINEI, tags=["古文", "敬語", "丁寧語", "侍り", "候ふ", "補助動詞", "聞き手敬意"]),
    make_textbook_entry(DOUBLE_KEIGO, tags=["古文", "敬語", "二重敬語", "せ給ふ", "させ給ふ", "最敬語", "帝", "中宮"]),
    make_textbook_entry(WAKA_RHETORIC, tags=["古文", "和歌", "修辞法", "枕詞", "序詞", "本歌取り", "体言止め", "倒置", "対句"]),
    make_textbook_entry(KAKEKOTOBA_ENGO, tags=["古文", "和歌", "掛詞", "縁語", "伊勢物語", "古今集", "百人一首", "小野小町"]),
    make_textbook_entry(KOBUN_JOSHIKI, tags=["古文", "古文常識", "平安貴族", "年中行事", "官位", "結婚", "衣装", "住居", "月の名称"]),
]

with open(OUTPUT, "w", encoding="utf-8") as f:
    json.dump({"textbooks": textbooks}, f, ensure_ascii=False, indent=2)

